const date = new Date();
const pad = (n) => (n < 10 ? '0' + n : n); // Helper function for padding

const formattedDate = `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())},${date.getMilliseconds()}`

return formattedDate;

